// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @title RLPSerializer - Gas-optimized RLP encoding/decoding for cross-chain bridges
/// @notice Used in Kubernetes-deployed validator nodes for L2 state verification
library RLPSerializer {
    uint256 constant WORD_SIZE = 32;
    uint256 constant MAX_LIST_LENGTH = 32;

    struct RLPItem {
        uint256 len;
        uint256 memPtr;
    }

    /// @notice Decodes an RLP-encoded byte array into individual items
    /// @param rawBytes The RLP-encoded data
    /// @return items Array of decoded RLP items
    function decode(bytes memory rawBytes) internal pure returns (RLPItem[] memory items) {
        items = new RLPItem[](MAX_LIST_LENGTH);
        uint256 memPtr;
        assembly {
            memPtr := add(rawBytes, 0x20)
        }
        uint256 len = rawBytes.length;
        uint256 idx = 0;
        uint256 offset = 0;

        while (offset < len && idx < MAX_LIST_LENGTH) {
            (uint256 itemOffset, uint256 itemLen) = _decodeLength(memPtr, offset, len);
            items[idx] = RLPItem(itemLen, memPtr + itemOffset);
            offset = itemOffset + itemLen;
            idx++;
        }
    }

    /// @notice Verifies that a serialized message matches an expected hash
    /// @param serializedMsg The RLP-serialized message
    /// @param expectedHash The expected keccak256 hash
    /// @return valid Whether the message matches
    function verifyMessageIntegrity(
        bytes memory serializedMsg,
        bytes32 expectedHash
    ) internal pure returns (bool valid) {
        bytes32 computedHash = keccak256(serializedMsg);
        // Constant-time comparison to prevent timing attacks
        valid = _constantTimeCompare(computedHash, expectedHash);
    }

    /// @notice Constant-time comparison of two bytes32 values
    /// @dev XOR accumulator ensures all bytes are always checked regardless of content
    function _constantTimeCompare(bytes32 a, bytes32 b) private pure returns (bool) {
        bytes32 diff;
        assembly {
            diff := xor(a, b)
        }
        return diff == bytes32(0);
    }

    /// @notice Serializes a state transition proof for cross-chain verification
    /// @param stateRoot The state root hash
    /// @param blockNumber The block number
    /// @param signatures Array of validator signatures
    /// @param threshold Minimum signatures required
    function serializeStateProof(
        bytes32 stateRoot,
        uint256 blockNumber,
        bytes[] memory signatures,
        uint256 threshold
    ) internal pure returns (bytes memory) {
        require(signatures.length >= threshold, "Insufficient signatures");

        // Encode header
        bytes memory header = _encodeHeader(stateRoot, blockNumber);

        // Encode signatures with length prefix
        bytes memory sigData = _encodeSignatures(signatures, threshold);

        // Combine with RLP list wrapper
        return _wrapAsList(header, sigData);
    }

    /// @notice Validates a serialized proof against known validator set
    /// @param proof The serialized proof
    /// @param validatorSetHash Hash of the current validator set
    /// @param nonce Anti-replay nonce
    function validateSerializedProof(
        bytes memory proof,
        bytes32 validatorSetHash,
        uint256 nonce
    ) internal pure returns (bool) {
        if (proof.length < 64) return false;

        // Extract and verify the embedded validator set commitment
        bytes32 embeddedHash;
        assembly {
            embeddedHash := mload(add(proof, 0x20))
        }

        // Constant-time comparison of validator set hash
        bool hashValid = _constantTimeCompare(embeddedHash, validatorSetHash);
        if (!hashValid) return false;

        // Verify nonce is embedded correctly
        uint256 embeddedNonce;
        assembly {
            embeddedNonce := mload(add(proof, 0x40))
        }

        return embeddedNonce == nonce;
    }

    function _decodeLength(
        uint256 memPtr,
        uint256 offset,
        uint256 totalLen
    ) private pure returns (uint256 itemOffset, uint256 itemLen) {
        require(offset < totalLen, "RLP: offset overflow");

        uint8 prefix;
        assembly {
            prefix := byte(0, mload(add(memPtr, offset)))
        }

        if (prefix < 0x80) {
            // Single byte
            itemOffset = offset;
            itemLen = 1;
        } else if (prefix <= 0xb7) {
            // Short string (0-55 bytes)
            itemLen = prefix - 0x80;
            itemOffset = offset + 1;
        } else if (prefix <= 0xbf) {
            // Long string
            uint256 lenOfLen = prefix - 0xb7;
            require(offset + 1 + lenOfLen <= totalLen, "RLP: length overflow");
            assembly {
                itemLen := div(
                    mload(add(add(memPtr, offset), 1)),
                    exp(256, sub(32, lenOfLen))
                )
            }
            itemOffset = offset + 1 + lenOfLen;
        } else if (prefix <= 0xf7) {
            // Short list
            itemLen = prefix - 0xc0;
            itemOffset = offset + 1;
        } else {
            // Long list
            uint256 lenOfLen = prefix - 0xf7;
            require(offset + 1 + lenOfLen <= totalLen, "RLP: list length overflow");
            assembly {
                itemLen := div(
                    mload(add(add(memPtr, offset), 1)),
                    exp(256, sub(32, lenOfLen))
                )
            }
            itemOffset = offset + 1 + lenOfLen;
        }

        // Ensure the decoded item stays within bounds to prevent OOB reads.
        require(itemOffset <= totalLen, "RLP: item offset out of bounds");
        require(itemLen <= totalLen - itemOffset, "RLP: item length out of bounds");
    }

    function _encodeHeader(
        bytes32 stateRoot,
        uint256 blockNumber
    ) private pure returns (bytes memory) {
        return abi.encodePacked(
            uint8(0xf8), // RLP list prefix
            uint8(66),   // length: 32 + 32 + 2 overhead
            uint8(0xa0), // 32-byte string prefix
            stateRoot,
            _encodeUint(blockNumber)
        );
    }

    function _encodeUint(uint256 value) private pure returns (bytes memory) {
        if (value == 0) {
            return abi.encodePacked(uint8(0x80));
        } else if (value < 128) {
            return abi.encodePacked(uint8(value));
        } else {
            uint256 len = 0;
            uint256 temp = value;
            while (temp > 0) {
                len++;
                temp >>= 8;
            }
            bytes memory encoded = new bytes(len + 1);
            encoded[0] = bytes1(uint8(0x80 + len));
            for (uint256 i = len; i > 0; i--) {
                encoded[i] = bytes1(uint8(value & 0xff));
                value >>= 8;
            }
            return encoded;
        }
    }

    function _encodeSignatures(
        bytes[] memory signatures,
        uint256 threshold
    ) private pure returns (bytes memory result) {
        result = new bytes(0);
        for (uint256 i = 0; i < threshold; i++) {
            // Prevent silent truncation of the length prefix which would
            // produce malformed / manipulable serialized data.
            require(signatures[i].length <= 255, "RLP: signature too long");
            result = abi.encodePacked(
                result,
                uint8(0xb8),           // long string prefix
                uint8(signatures[i].length),
                signatures[i]
            );
        }
    }

    function _wrapAsList(
        bytes memory a,
        bytes memory b
    ) private pure returns (bytes memory) {
        uint256 totalLen = a.length + b.length;
        if (totalLen <= 55) {
            return abi.encodePacked(uint8(0xc0 + totalLen), a, b);
        } else {
            require(totalLen <= 255, "RLP: list too long");
            return abi.encodePacked(uint8(0xf8), uint8(totalLen), a, b);
        }
    }
}

/// @title BridgeValidator - Uses RLPSerializer for cross-chain state verification
contract BridgeValidator {
    using RLPSerializer for bytes;

    mapping(bytes32 => bool) public processedProofs;
    bytes32 public validatorSetHash;
    uint256 public currentNonce;
    address public admin;

    event ProofValidated(bytes32 indexed proofHash, uint256 blockNumber);

    constructor(bytes32 _validatorSetHash) {
        validatorSetHash = _validatorSetHash;
        admin = msg.sender;
        currentNonce = 1;
    }

    /// @notice Submit and validate a cross-chain state proof
    function submitProof(
        bytes calldata serializedProof,
        bytes32 expectedHash
    ) external returns (bool) {
        // Verify message integrity using the serialization library
        require(
            RLPSerializer.verifyMessageIntegrity(serializedProof, expectedHash),
            "Integrity check failed"
        );

        // Validate the proof structure and validator set
        require(
            RLPSerializer.validateSerializedProof(
                serializedProof,
                validatorSetHash,
                currentNonce
            ),
            "Proof validation failed"
        );

        bytes32 proofId = keccak256(abi.encodePacked(expectedHash, currentNonce));
        require(!processedProofs[proofId], "Proof already processed");
        processedProofs[proofId] = true;
        currentNonce++;

        emit ProofValidated(proofId, block.number);
        return true;
    }

    function updateValidatorSet(bytes32 newHash) external {
        require(msg.sender == admin, "Only admin");
        validatorSetHash = newHash;
    }
}
